// Validate employee data
const employee = $input.first().json.body || $input.first().json;

// Required fields
const required = ['name', 'email', 'department', 'role', 'start_date', 'manager'];
const missing = required.filter(field => !employee[field]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Validate email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(employee.email)) {
  throw new Error('Invalid work email format');
}

// Format start date for Vietnamese locale
const startDate = new Date(employee.start_date);
const startDateFormatted = startDate.toLocaleDateString('vi-VN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

// Employee ID generation
const employeeId = `EMP-${Date.now().toString().slice(-6)}`;

const sanitized = {
  employee_id: employeeId,
  name: employee.name.trim(),
  email: employee.email.toLowerCase().trim(),
  personal_email: employee.personal_email?.toLowerCase().trim() || employee.email,
  department: employee.department.trim(),
  role: employee.role.trim().toLowerCase(),
  start_date: employee.start_date,
  start_date_formatted: startDateFormatted,
  manager: employee.manager.trim(),
  manager_email: employee.manager_email?.trim() || '',
  address: employee.address?.trim() || 'Not provided',
  status: 'onboarding_initiated',
  created_at: new Date().toISOString(),
  timezone: 'Asia/Ho_Chi_Minh',
  accounts_created: [],
  equipment_assigned: []
};

console.log(`Onboarding started for ${sanitized.name} (${sanitized.employee_id})`);

return [{ json: sanitized }];

// Generate welcome email content
const emp = $input.first().json;

const firstDayAgenda = `
📅 Lịch trình ngày đầu tiên:

9:00 AM  - Welcome meeting với HR
10:00 AM - IT setup (laptop, accounts)
11:00 AM - Team introductions
12:00 PM - Lunch với team
2:00 PM  - Role overview với manager: ${emp.manager}

📍 Địa điểm: Văn phòng công ty / Remote

📝 Mang theo:
- CMND/CCCD
- Thông tin ngân hàng (cho payroll)
- Emergency contact details
`;

const welcomeEmail = {
  to: emp.personal_email, // Send to personal email before work email is active
  cc: emp.manager_email,
  subject: `🎉 Chào mừng ${emp.name} đến với đội ngũ công ty!`,
  body: `Dear ${emp.name},

🎉 Chúng tôi rất vui chào mừng bạn đến với đội ngũ!

📅 Ngày bắt đầu: ${emp.start_date_formatted}
🕐 Thời gian: 9:00 AM
📍 Địa điểm: Văn phòng công ty / Remote

📧 Tài khoản work email của bạn: ${emp.email}
🔒 Mật khẩu tạm thời: Sẽ được gửi qua SMS/Zalo

${firstDayAgenda}

Nếu bạn có bất kỳ câu hỏi nào trước ngày bắt đầu, vui lòng liên hệ:
📧 HR: hr@company.com
📞 Hotline: 1900-XXXX

Chào mừng bạn! 🚀

Trân trọng,
Bộ phận Nhân sự`,
  emp_data: emp
};

return [{ json: { ...welcomeEmail, ...emp } }];

// Assign equipment based on role
const emp = $input.first().json;

// Equipment mapping by role
const EQUIPMENT = {
  standard: ['Laptop', 'Monitor', 'Keyboard', 'Mouse', 'Headset'],
  developer: ['Laptop', 'Monitor', 'Keyboard', 'Mouse', 'Headset', 'Docking Station'],
  designer: ['Laptop', 'Monitor', 'Keyboard', 'Mouse', 'Headset', 'Drawing Tablet'],
  sales: ['Laptop', 'Headset', 'Mobile Phone'],
  manager: ['Laptop', 'Monitor', 'Keyboard', 'Mouse', 'Headset']
};

const roleEquipment = EQUIPMENT[emp.role] || EQUIPMENT.standard;

// Equipment delivery date (3 days before start)
const deliveryDate = new Date(new Date(emp.start_date).getTime() - 3*24*60*60*1000);

const equipment = {
  employee: emp.name,
  employee_id: emp.employee_id,
  department: emp.department,
  role: emp.role,
  equipment_list: roleEquipment,
  delivery_address: emp.address,
  delivery_date: deliveryDate.toISOString().split('T')[0],
  start_date: emp.start_date,
  status: 'pending_delivery'
};

console.log(`Equipment for ${emp.name} (${emp.role}): ${roleEquipment.join(', ')}`);

return [{ json: { ...equipment, emp_data: emp } }];

